module day_checker(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] day1,\n    input [2:0] day2,\n    output reg result,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] COMPLETE = 2'd2;\n    \n    // Internal registers\n    reg [1:0] state;\n    reg [2:0] diff;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 1'b0;\n            done <= 1'b0;\n            diff <= 3'd0;\n            cycle_count <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    diff <= (day2 - day1 + 7) % 7;\n                    \n                    if (diff == 3'd0 || diff == 3'd2 || diff == 3'd3) begin\n                        result <= 1'b1;\n                    end else begin\n                        result <= 1'b0;\n                    end\n                    \n                    if (cycle_count >= MAX_CYCLES) begin\n                        state <= COMPLETE;\n                    end else begin\n                        state <= COMPLETE;\n                    end\n                end\n                \n                COMPLETE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule